const errorData = $input.first().json;

const workflowName = errorData.workflow?.name || 'Desconocido';
const workflowId = errorData.workflow?.id || 'N/A';
const lastNode = errorData.execution?.lastNodeExecuted || 'Desconocido';
const errorMessage = errorData.execution?.error?.message || 'Sin mensaje de error';
const errorStack = errorData.execution?.error?.stack || 'Sin stack trace';
const executionId = errorData.execution?.id || 'N/A';
const executionMode = errorData.execution?.mode || 'N/A';
const timestamp = new Date().toLocaleString('es-GT', { timeZone: 'America/Guatemala' });

const n8nBaseUrl = 'https://flexcrmtest.app.n8n.cloud';
const executionUrl = `${n8nBaseUrl}/workflow/${workflowId}/executions/${executionId}`;

let severity = 'MEDIA';
let severityEmoji = '🟡';
if (executionMode === 'trigger' || executionMode === 'webhook') {
  severity = 'ALTA';
  severityEmoji = '🔴';
} else if (executionMode === 'manual') {
  severity = 'BAJA';
  severityEmoji = '🟢';
}

const severityColor = severity === 'ALTA' ? '#dc3545' : severity === 'MEDIA' ? '#fd7e14' : '#28a745';

const teamsMessage = {
  "@type": "MessageCard",
  "@context": "http://schema.org/extensions",
  "themeColor": severity === 'ALTA' ? 'FF0000' : severity === 'MEDIA' ? 'FFA500' : '00FF00',
  "summary": `Error en n8n: ${workflowName}`,
  "sections": [{
    "activityTitle": `${severityEmoji} Error en Workflow de n8n`,
    "activitySubtitle": timestamp,
    "facts": [
      { "name": "Workflow", "value": workflowName },
      { "name": "Workflow ID", "value": workflowId },
      { "name": "Nodo con Error", "value": lastNode },
      { "name": "Severidad", "value": `${severityEmoji} ${severity}` },
      { "name": "Modo", "value": executionMode },
      { "name": "Ejecución ID", "value": String(executionId) },
      { "name": "Error", "value": errorMessage }
    ],
    "markdown": true
  }],
  "potentialAction": [{
    "@type": "OpenUri",
    "name": "Ver Ejecución en n8n",
    "targets": [{ "os": "default", "uri": executionUrl }]
  }]
};

const teamsHtml = `<div style="font-family:Segoe UI,sans-serif;">
<h2 style="color:${severityColor};margin:0 0 8px 0;">${severityEmoji} Error en Workflow de n8n</h2>
<p style="color:#666;margin:0 0 16px 0;">${timestamp}</p>
<table style="border-collapse:collapse;width:100%;">
<tr><td style="padding:8px 12px;border-bottom:1px solid #eee;color:#888;font-weight:600;">Workflow</td><td style="padding:8px 12px;border-bottom:1px solid #eee;">${workflowName}</td></tr>
<tr><td style="padding:8px 12px;border-bottom:1px solid #eee;color:#888;font-weight:600;">Workflow ID</td><td style="padding:8px 12px;border-bottom:1px solid #eee;">${workflowId}</td></tr>
<tr><td style="padding:8px 12px;border-bottom:1px solid #eee;color:#888;font-weight:600;">Nodo con Error</td><td style="padding:8px 12px;border-bottom:1px solid #eee;color:#856404;font-weight:600;">${lastNode}</td></tr>
<tr><td style="padding:8px 12px;border-bottom:1px solid #eee;color:#888;font-weight:600;">Severidad</td><td style="padding:8px 12px;border-bottom:1px solid #eee;font-weight:700;color:${severityColor};">${severityEmoji} ${severity}</td></tr>
<tr><td style="padding:8px 12px;border-bottom:1px solid #eee;color:#888;font-weight:600;">Modo</td><td style="padding:8px 12px;border-bottom:1px solid #eee;">${executionMode}</td></tr>
<tr><td style="padding:8px 12px;border-bottom:1px solid #eee;color:#888;font-weight:600;">Ejecución ID</td><td style="padding:8px 12px;border-bottom:1px solid #eee;">${executionId}</td></tr>
</table>
<div style="background-color:#fdf2f2;border-left:4px solid #dc3545;padding:12px 16px;margin:16px 0;border-radius:4px;">
<strong style="color:#dc3545;">Error:</strong><br/>
<code style="color:#721c24;">${errorMessage}</code>
</div>
<a href="${executionUrl}" style="display:inline-block;background-color:#10254e;color:#ffffff;padding:10px 24px;text-decoration:none;border-radius:6px;font-weight:600;margin-top:8px;">Ver Ejecución en n8n →</a>
<p style="color:#999;font-size:12px;margin-top:16px;">Grupo Apolo • Dirección de IT • Coordinación de Ciberseguridad</p>
</div>`;

const emailHtml = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#eef1f5;font-family:'Segoe UI',Tahoma,Geneva,Verdana,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#eef1f5;padding:30px 10px;"><tr><td align="center"><table role="presentation" width="650" cellpadding="0" cellspacing="0" style="background-color:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 4px 24px rgba(0,0,0,0.08);"><tr><td style="background:linear-gradient(135deg,#10254e 0%,#1a3a6e 50%,#10254e 100%);padding:40px 40px 30px 40px;text-align:center;"><img src="https://raw.githubusercontent.com/BraulioApolo/LogosApolo/main/Logotipo-Apolo-version-blanco.png" alt="Grupo Apolo" width="280" style="display:block;margin:0 auto 25px auto;max-width:280px;height:auto;filter:brightness(1.15);"><table role="presentation" width="60" cellpadding="0" cellspacing="0" style="margin:0 auto 20px auto;"><tr><td style="height:3px;background:linear-gradient(90deg,transparent,#00d9ff,transparent);border-radius:2px;"></td></tr></table><h1 style="margin:0;font-size:22px;font-weight:600;color:#ffffff;letter-spacing:1px;text-transform:uppercase;">Alerta de Error en Automatización</h1><p style="margin:8px 0 0 0;font-size:13px;color:rgba(255,255,255,0.7);letter-spacing:0.5px;">Dirección de IT &bull; Monitoreo de Workflows</p></td></tr><tr><td style="padding:0;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="background-color:${severityColor};padding:14px 40px;text-align:center;"><span style="font-size:14px;font-weight:700;color:#ffffff;letter-spacing:1.5px;text-transform:uppercase;">${severityEmoji} SEVERIDAD: ${severity}</span></td></tr></table></td></tr><tr><td style="padding:20px 40px 0 40px;text-align:right;"><span style="font-size:12px;color:#8c95a1;letter-spacing:0.3px;">${timestamp}</span></td></tr><tr><td style="padding:15px 40px 30px 40px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f8f9fb;border-radius:12px;overflow:hidden;margin-bottom:20px;"><tr><td style="padding:16px 20px;border-bottom:1px solid #e9ecef;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="140" style="font-size:12px;font-weight:600;color:#8c95a1;text-transform:uppercase;letter-spacing:0.8px;vertical-align:top;padding-top:2px;">Workflow</td><td style="font-size:15px;font-weight:600;color:#10254e;">${workflowName}</td></tr></table></td></tr><tr><td style="padding:16px 20px;border-bottom:1px solid #e9ecef;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="140" style="font-size:12px;font-weight:600;color:#8c95a1;text-transform:uppercase;letter-spacing:0.8px;vertical-align:top;padding-top:2px;">Workflow ID</td><td style="font-size:14px;color:#495057;font-family:'Consolas','Courier New',monospace;">${workflowId}</td></tr></table></td></tr><tr><td style="padding:16px 20px;border-bottom:1px solid #e9ecef;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="140" style="font-size:12px;font-weight:600;color:#8c95a1;text-transform:uppercase;letter-spacing:0.8px;vertical-align:top;padding-top:2px;">Nodo con Error</td><td><span style="display:inline-block;background-color:#fff3cd;color:#856404;font-size:13px;font-weight:600;padding:4px 12px;border-radius:6px;border:1px solid #ffc107;">${lastNode}</span></td></tr></table></td></tr><tr><td style="padding:16px 20px;border-bottom:1px solid #e9ecef;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="140" style="font-size:12px;font-weight:600;color:#8c95a1;text-transform:uppercase;letter-spacing:0.8px;vertical-align:top;padding-top:2px;">Modo</td><td style="font-size:14px;color:#495057;">${executionMode}</td></tr></table></td></tr><tr><td style="padding:16px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="140" style="font-size:12px;font-weight:600;color:#8c95a1;text-transform:uppercase;letter-spacing:0.8px;vertical-align:top;padding-top:2px;">Ejecución ID</td><td style="font-size:13px;color:#6c757d;font-family:'Consolas','Courier New',monospace;">${executionId}</td></tr></table></td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#fdf2f2;border-radius:12px;overflow:hidden;border-left:4px solid #dc3545;margin-bottom:20px;"><tr><td style="padding:20px;"><p style="margin:0 0 8px 0;font-size:11px;font-weight:700;color:#dc3545;text-transform:uppercase;letter-spacing:1px;">Mensaje de Error</p><p style="margin:0;font-size:14px;color:#721c24;font-family:'Consolas','Courier New',monospace;line-height:1.6;word-break:break-word;">${errorMessage}</p></td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f0f2f5;border-radius:12px;overflow:hidden;margin-bottom:25px;"><tr><td style="padding:20px;"><p style="margin:0 0 10px 0;font-size:11px;font-weight:700;color:#6c757d;text-transform:uppercase;letter-spacing:1px;">Stack Trace</p><div style="background-color:#1e1e2e;border-radius:8px;padding:16px;overflow-x:auto;"><pre style="margin:0;font-size:11px;color:#a9b7c6;font-family:'Consolas','Courier New',monospace;line-height:1.5;white-space:pre-wrap;word-break:break-word;">${errorStack}</pre></div></td></tr></table><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:5px 0 10px 0;"><a href="${executionUrl}" target="_blank" style="display:inline-block;background:linear-gradient(135deg,#10254e 0%,#1a3a6e 100%);color:#ffffff;font-size:14px;font-weight:600;text-decoration:none;padding:14px 40px;border-radius:8px;letter-spacing:0.5px;">Ver Ejecución en n8n →</a></td></tr></table></td></tr><tr><td style="background-color:#10254e;padding:25px 40px;text-align:center;"><p style="margin:0 0 6px 0;font-size:12px;color:rgba(255,255,255,0.6);letter-spacing:0.3px;">Alerta generada automáticamente por n8n Error Handler</p><p style="margin:0;font-size:11px;color:rgba(255,255,255,0.4);">Grupo Apolo &bull; Dirección de IT &bull; Coordinación de Ciberseguridad</p></td></tr></table></td></tr></table></body></html>`;

const emailSubject = `${severityEmoji} [n8n Error] ${workflowName} - Nodo: ${lastNode} (${severity})`;

return [{
  json: {
    workflowName,
    workflowId,
    lastNode,
    errorMessage,
    errorStack,
    executionId,
    executionMode,
    executionUrl,
    timestamp,
    severity,
    severityEmoji,
    teamsMessage,
    teamsHtml,
    emailHtml,
    emailSubject
  }
}];

return [{
  json: {
    status: 'logged',
    message: `Error de severidad ${$input.first().json.severity} registrado. Solo se notificó por email y canal general de Teams.`,
    timestamp: $input.first().json.timestamp
  }
}];
